'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const heights = data.slice(1);
const order = Array.from({ length: n }, (_, i) => i);
order.sort((a, b) => heights[b] - heights[a]);

const parent = new Int32Array(n);
const size = new Int32Array(n);
const active = new Uint8Array(n);

function find(x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function unite(a, b) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return false;

  if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
  parent[rb] = ra;
  size[ra] += size[rb];
  return true;
}

let components = 0;
let maxComponents = 0;

for (let i = 0; i < n;) {
  let j = i;
  const height = heights[order[i]];

  while (j < n && heights[order[j]] === height) {
    const idx = order[j];
    active[idx] = 1;
    parent[idx] = idx;
    size[idx] = 1;
    components++;
    j++;
  }

  for (let k = i; k < j; k++) {
    const idx = order[k];
    if (idx > 0 && active[idx - 1] && unite(idx, idx - 1)) components--;
    if (idx + 1 < n && active[idx + 1] && unite(idx, idx + 1)) components--;
  }

  maxComponents = Math.max(maxComponents, components);
  i = j;
}

console.log(maxComponents + 1);
